var RenovationCatalog=(()=>{
function selections(plan,taskId,type){return (plan.resources||[]).filter(r=>r.type===type&&(r.taskIds||[]).includes(taskId)).map(r=>r.catalogId?'c:'+r.catalogId:'p:'+r.id)}
function assign(plan,taskId,selected,catalog,uid){const next=JSON.parse(JSON.stringify(plan)),wanted=new Set(selected),entries=catalog.entries||[];for(const r of next.resources){const key=r.catalogId?'c:'+r.catalogId:'p:'+r.id;if((r.taskIds||[]).includes(taskId)&&!wanted.has(key))r.taskIds=r.taskIds.filter(id=>id!==taskId)}for(const key of wanted){if(key.startsWith('p:')){const r=next.resources.find(r=>r.id===key.slice(2));if(r)r.taskIds=[...new Set([...(r.taskIds||[]),taskId])]}else if(key.startsWith('c:')){const entry=entries.find(e=>e.id===key.slice(2)&&['material','werkzeug'].includes(e.type));if(!entry)continue;let r=next.resources.find(r=>r.catalogId===entry.id);if(!r){r={id:uid(),catalogId:entry.id,type:entry.type,label:entry.label,unit:entry.unit,unitPrice:Number(entry.unitPrice)||0,qty:0,status:'offen',costMode:'included',supplier:entry.supplier||'',url:entry.url||'',notes:entry.notes||'',taskIds:[]};next.resources.push(r)}r.taskIds=[...new Set([...(r.taskIds||[]),taskId])]}}return next}
return {selections,assign};})();
if(typeof module!=='undefined')module.exports=RenovationCatalog;
